-- PT102-S4-Q20. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT102-S4-Q20$batch12$ AND q.stimulus=$batch12$In some ill-considered popularizations of interesting current research, it is argued that higher apes have the capacity for language but have never put it to use—a remarkable biological miracle, given the enormous selectional advantage of even minimal linguistic skills. It is rather like claiming that some animal has wings adequate for flight but has never thought to fly.$batch12$ AND q.prompt=$batch12$Which one of the following is most similar in its reasoning to the argument above?$batch12$ AND q.correct_choice=$batch12$C$batch12$) THEN RAISE EXCEPTION 'Question changed: PT102-S4-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT102-S4-Q20$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S4-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT102-S4-Q20$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The claim that apes have language capacity but never use it is ill-considered.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Language gives an enormous advantage. Having the capacity and never using it would be like having wings fit for flight and never flying.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The argument ridicules a claim that a creature has a useful built-in ability that it has never once used. It makes the point by comparing it to an obvious physical ability left unused.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Claim that an ability exists but has never been used is compared to a body part never used for its obvious job.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT102-S4-Q20$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Never sleeping and a meat-free lion aren't about an unused ability.$batch12$), ($batch12$B$batch12$, $batch12$Visiting without founding cities isn't an unused capacity.$batch12$), ($batch12$C$batch12$, $batch12$Telekinetic powers that no human has ever used are compared to an insect with legs that never walks. Same move.$batch12$), ($batch12$D$batch12$, $batch12$Growing tobacco without smoking it is a choice people could easily make, often to sell the crop. It isn't an absurdly unused built-in ability.$batch12$), ($batch12$E$batch12$, $batch12$Not everyone with a car drives it. That is ordinary, not absurd.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT102-S4-Q20$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
